<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('overtime.view_own');verify_csrf();$pdo=staff_db();$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'&&can('overtime.submit')){$s=$pdo->prepare("INSERT INTO overtime_requests(staff_id,overtime_date,start_time,end_time,total_hours,reason) VALUES(?,?,?,?,?,?)");$s->execute([$staff['id'],$_POST['overtime_date'],$_POST['start_time'],$_POST['end_time'],max(0,(strtotime($_POST['end_time'])-strtotime($_POST['start_time']))/3600),trim($_POST['reason'])]);flash('success','Request submitted.');staff_redirect('staff/pages/overtime.php');}
$s=$pdo->prepare("SELECT r.*,r.reason detail FROM overtime_requests r WHERE r.staff_id=? ORDER BY r.created_at DESC");$s->execute([$staff['id']]);$rows=$s->fetchAll();
$pageTitle='Overtime';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Requests</p><h1>Overtime</h1></div></div><div class="split-grid"><section class="staff-panel"><h2>New request</h2><form method="post"><?= csrf_field() ?>
    <label>Date<input type="date" name="overtime_date" required></label><div class="two"><label>Start<input type="time" name="start_time" required></label><label>End<input type="time" name="end_time" required></label></div><label>Reason<textarea name="reason" required></textarea></label>
    <button class="btn primary">Submit request</button></form></section><section class="staff-panel table-panel"><h2>My requests</h2><table><thead><tr><th>Details</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['detail']??$r['reason']??'') ?></td><td><span class="pill <?= h($r['status']) ?>"><?= h($r['status']) ?></span></td><td><?= h(date('j M Y',strtotime($r['created_at']))) ?></td></tr><?php endforeach;?></tbody></table></section></div></main><?php require __DIR__.'/../../includes/staff/footer.php';?>